#include <bits/stdc++.h>
using namespace std;

int compute_power(int base, int exp, int mod) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return result;
}

const int MAXN = 300005;
unsigned long long dp_table[27][MAXN];
int factorials[MAXN], inv_factorials[MAXN];

int permutation(int n, int m, int mod) {
    return (long long)factorials[n] * inv_factorials[n - m] % mod;
}

int main() {
    int n, K, MOD;
    scanf("%d %d %d", &n, &K, &MOD);
    if (n % 2 == 1) {
        printf("%d\n", compute_power(K, n, MOD));
        return 0;
    }
    factorials[0] = 1;
    for (int i = 1; i <= n; ++i) {
        factorials[i] = (long long)factorials[i - 1] * i % MOD;
    }
    inv_factorials[n] = compute_power(factorials[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
        inv_factorials[i] = (long long)inv_factorials[i + 1] * (i + 1) % MOD;
    }
    dp_table[0][0] = 1ULL;
    for (int k = 0; k < K; ++k) {
        for (int i = 1; i <= n; ++i) {
            if ((i & n) != i) continue;
            int block_size = 1 << (31 - __builtin_clz(i));
            unsigned long long &res = dp_table[k + 1][i];
            res = 0ULL;
            for (int j = i - block_size; j >= 0; j = (j - 1) & i) {
                int j_plus = j + block_size;
                res += dp_table[k][i ^ j_plus] * inv_factorials[j_plus];
                if (++cnt == 17) {
                    res %= MOD;
                    cnt = 0;
                }
                if (j == 0) break;
            }
            res %= MOD;
        }
    }
    int total = 0;
    for (int i = 0; i <= K; ++i) {
        total = (total + (long long)factorials[n] * dp_table[i][n] % MOD * permutation(K, i, MOD)) % MOD;
    }
    printf("%d\n", (compute_power(K, n, MOD) + MOD - total) % MOD);
}
